}

type Obj struct {
	list  []string
	index int
	max   int
}

func (o *Obj) hasNext() bool {
	return o.index < o.max
}

func (o *Obj) next() string {
	if o.hasNext() {
		res := o.list[o.index]
		o.index++
		return res
	}
	panic("ArrayIndexOutOfBoundsException There is no more input")
}

func init(input []string) *Obj {
	return &Obj{list: input, index: 0, max: len(input)}
}

func nextInt(obj *Obj) int {
	return myconv(obj.next(), 1)
}

func nextStrArray(obj *Obj) []string {
	return myconv(obj.next(), 2)
}

func nextIntArray(obj *Obj) []int {
	return myconv(obj.next(), 4)
}

func nextCharArray(obj *Obj) []string {
	return myconv(obj.next(), 6)
}

func myconv(i string, no int) interface{} {
	switch no {
	case 1:
		var x int
		fmt.Sscanf(i, "%d", &x)
		return x
	case 2:
		return splitSpace(i)
	case 4:
		return splitSpaceInt(i)
	case 6:
		return splitChar(i)
	case 7:
		return splitCharInt(i)
	case 8:
		return joinSpace(i)
	case 9:
		return joinNewline(i)
	case 0:
		return joinNoChar(i)
	default:
		return i
	}
}

func splitSpace(s string) []string {
	var res []string
	var current string
	for _, c := range s {
		if c == ' ' {
			if current != "" {
				res = append(res, current)
				current = ""
			}
		} else {
			current += string(c)
		}
	}
	if current != "" {
		res = append(res, current)
	}
	return res
}

func splitSpaceInt(s string) []int {
	parts := splitSpace(s)
	res := make([]int, len(parts))
	for i, p := range parts {
		var x int
		fmt.Sscanf(p, "%d", &x)
		res[i] = x
	}
	return res
}

func splitChar(s string) []string {
	res := make([]string, len(s))
	for i, c := range s {
		res[i] = string(c)
	}
	return res
}

func splitCharInt(s string) []int {
	res := make([]int, len(s))
	for i, c := range s {
		res[i] = int(c - '0')
	}
	return res
}

func joinSpace(arr []string) string {
	return join(arr, " ")
}

func joinNewline(arr []string) string {
	return join(arr, "\n")
}

func joinNoChar(arr []string) string {
	return join(arr, "")
}

func join(arr []string, sep string) string {
	if len(arr) == 0 {
		return ""
	}
	res := arr[0]
	for _, s := range arr[1:] {
		res += sep + s
	}
	return res
}

func myout(s interface{}) {
	fmt.Println(s)
}

func myerr(s interface{}) {
